function rows(name) {
  try { return $(name).all().map(i => i.json || {}).filter(r => Object.keys(r).length); }
  catch { return []; }
}
function s(v) { return String(v ?? '').trim(); }
function up(v) { return s(v).toUpperCase(); }
function has(v) { return s(v) !== ''; }
function localStamp(d = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Warsaw', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
  }).format(d);
}
function dateOnly(d = new Date()) { return localStamp(d).slice(0, 10); }
function parseDate(v) {
  const x = s(v);
  if (!x) return null;
  const normalized = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}/.test(x) ? x.replace(' ', 'T') : x;
  const d = new Date(normalized);
  return Number.isNaN(d.getTime()) ? null : d;
}
function withinDays(v, days) {
  const d = parseDate(v); if (!d) return false;
  const age = Date.now() - d.getTime();
  return age >= 0 && age <= days * 86400000;
}
function futureWithin(v, days) {
  const d = parseDate(v); if (!d) return false;
  const diff = d.getTime() - Date.now();
  return diff >= 0 && diff <= days * 86400000;
}
function earliest(values) {
  return values.map(v => ({raw:s(v), d:parseDate(v)})).filter(x => x.d && x.d.getTime() >= Date.now())
    .sort((a,b) => a.d - b.d)[0]?.raw || '';
}
function closed(v) {
  return /(ODRZUC|ZAMKNI|CLOSED|SKIPPED|NIEAKTUAL|ARCHIVED|DONE|COMPLETED|WYSŁANO|ZGŁOSZONE)/i.test(s(v));
}
function handled(v) {
  return /(DONE|HANDLED|CLOSED|RESOLVED|OBSŁUŻ|COMPLETED)/i.test(s(v));
}
function validAsset(r) {
  const id = s(r.Asset_Drive_ID), url = s(r.Asset_URL);
  if (!id || !url) return false;
  if (/\/folders\//i.test(url)) return false;
  return /\/file\/d\//i.test(url) || /uc\?id=/i.test(url) || /\.(mp4|mov|jpg|jpeg|png|webp)(\?|$)/i.test(url);
}

const outreach = rows('GS — OUTREACH_LOG');
const opportunities = rows('GS — OPPORTUNITIES').filter(r => has(r.Opportunity_ID));
const supports = rows('GS — SUPPORT_TARGETS').filter(r => has(r.Target_ID));
const submissions = rows('GS — SUBMISSION_LOG').filter(r => has(r.Log_ID));
const social = rows('GS — SOCIAL_QUEUE').filter(r => has(r.Item_ID) && up(r.Item_ID) !== 'QUEUE-0000');
const seoTasks = rows('GS — SEO_TASKS').filter(r => has(r.Task_ID));
const aiRows = rows('GS — AI_VISIBILITY').filter(r => has(r.Check_ID));
const media = rows('GS — MEDIA_RESULTS').filter(r => has(r.Result_ID) && !/^WZÓR/i.test(s(r.Result_ID)));
const playlist = rows('GS — PLAYLIST_RESULTS').filter(r => has(r.Placement_ID) && !/^WZÓR/i.test(s(r.Placement_ID)));

const replyAction = outreach.filter(r => has(r.Reply_At) && !handled(r.Discord_Status) && !handled(r.Status));
const followupsDue = outreach.filter(r => has(r.Follow_Up_At) && !has(r.Reply_At) && parseDate(r.Follow_Up_At)?.getTime() <= Date.now());
const urgentOpps = opportunities.filter(r => up(r.Priority) === 'A' && !closed(r.Status) && futureWithin(r.Deadline, 14));
const supportReady = supports.filter(r => /^A\b/i.test(s(r.Tier)) && !closed(r.Status) && /(SZKIC GOTOWY|DO KONTAKTU)/i.test(s(r.Status)));
const socialReady = social.filter(r => up(r.Status) === 'READY_FOR_APPROVAL');
const socialValid = socialReady.filter(validAsset);
const socialInvalid = socialReady.length - socialValid.length;
const seoDue = seoTasks.filter(r => !closed(r.Status) && futureWithin(r.Due_At, 7));

const sent30 = outreach.filter(r => has(r.Gmail_Message_ID) && withinDays(r.Sent_At, 30));
const replies30 = outreach.filter(r => withinDays(r.Reply_At, 30));
const media30 = media.filter(r => has(r.URL) && withinDays(r.Published_At, 30));
const playlist30 = playlist.filter(r => has(r.Placement_URL) && withinDays(r.Start_At, 30));
const social30 = social.filter(r => (has(r.IG_Media_ID) || has(r.FB_Post_ID) || has(r.Published_At)) && withinDays(r.Published_At, 30));
const opps30 = opportunities.filter(r => /^OPP-/i.test(s(r.Opportunity_ID)) && withinDays(r.Found_At, 30));

const nextFollowup = earliest(outreach.filter(r => !has(r.Reply_At)).map(r => r.Follow_Up_At));
const nextDeadline = earliest(opportunities.filter(r => !closed(r.Status)).map(r => r.Deadline));
const nextSocial = earliest(social.filter(r => up(r.Status) === 'APPROVED' && validAsset(r)).map(r => r.Suggested_Publish_At));

const latestAI = aiRows.slice().sort((a,b) => (parseDate(b.Checked_At)?.getTime()||0) - (parseDate(a.Checked_At)?.getTime()||0))[0] || {};
const aiLimited = up(latestAI.Content_Gap) === 'RATE_LIMITED' || up(latestAI.Query) === '__RATE_LIMITED__';
const aiError = has(latestAI.Content_Gap) && !['RATE_LIMITED',''].includes(up(latestAI.Content_Gap));
const aiValue = aiLimited ? 'RATE_LIMITED' : aiError ? 'ERROR' : has(latestAI.Checked_At) ? 'OK' : 'BRAK DANYCH';
const aiStatus = aiLimited || aiError ? 'UWAGA' : has(latestAI.Checked_At) ? 'OK' : 'INFO';

const freshnessCandidates = [
  ...outreach.flatMap(r => [r.Last_Synced_At, r.Reply_At, r.Sent_At]),
  ...opportunities.map(r => r.Found_At),
  ...social.map(r => r.Created_At),
  ...aiRows.map(r => r.Checked_At)
].filter(has);
const latestActivity = freshnessCandidates.map(parseDate).filter(Boolean).sort((a,b)=>b-a)[0];
const freshHours = latestActivity ? (Date.now()-latestActivity.getTime())/3600000 : Infinity;
const refresh = localStamp();

const links = {
  outreach:'https://docs.google.com/spreadsheets/d/1P9FqB7brPc6fZ2dkJMFCc3cVyKbcIjSAvMas-3mZD4g/edit',
  scout:'https://docs.google.com/spreadsheets/d/1aeOq_LFPp7HmFnNCenjz0RA5wIATgfd--ycbmmAGEk4/edit',
  social:'https://docs.google.com/spreadsheets/d/1nav2ituUQ6MxY7NV6tds3AXTiPzqur1hS8Hg-wDjdl0/edit',
  seo:'https://docs.google.com/spreadsheets/d/1RWqTUo2eJvG8OngqMfiyAFu5tkvSgVBl3FZNIU6nDNc/edit',
  results:'https://docs.google.com/spreadsheets/d/1wrfH2R7J8iiGn2zhKKsqytq92vK_gKOOQjkyEwsGu3s/edit',
  cockpit:'https://docs.google.com/spreadsheets/d/1jjt266IE0AsZkGRrVmWT60FQoOqKFWUkNUlzKIkTjmY/edit',
  backend:'https://drive.google.com/drive/folders/1a1qgW0IF9waN32XIKy34NGHAI2JJy6HL'
};
function metric(id, area, label, value, status, detail, link) {
  return {Metric_ID:id, Obszar:area, Wskaźnik:label, Wartość:value, Status:status, 'Co to znaczy':detail, Odświeżono:refresh, Link:link};
}
const out = [
  metric('DEC_REPLY','DO DECYZJI','Odpowiedzi wymagające reakcji',replyAction.length,replyAction.length?'PILNE':'OK','Nowa odpowiedź znika z tej liczby po oznaczeniu jej jako obsłużonej.',links.outreach),
  metric('DEC_FOLLOWUP','DO DECYZJI','Follow-upy należne teraz',followupsDue.length,followupsDue.length?'UWAGA':'OK','Wyliczane z Sent_At, Follow_Up_At i braku Reply_At.',links.outreach),
  metric('DEC_OPPORTUNITY','DO DECYZJI','Pilne okazje priorytetu A',urgentOpps.length,urgentOpps.length?'PILNE':'OK','Tylko otwarte okazje z potwierdzonym terminem w ciągu 14 dni.',links.scout),
  metric('DEC_SUPPORT','DO DECYZJI','Supporty gotowe do konkretnego pitchu',supportReady.length,supportReady.length?'UWAGA':'OK','Aktywne cele Tier A ze statusem Szkic gotowy lub Do kontaktu.',links.scout),
  metric('DEC_SOCIAL','DO DECYZJI','Posty z poprawnym assetem do akceptacji',`${socialValid.length} / ${socialInvalid}`,socialValid.length?'UWAGA':socialInvalid?'PILNE':'OK','Pierwsza liczba: realne pliki do decyzji. Druga: rekordy z nieprawidłowym assetem.',links.social),
  metric('DEC_SEO','DO DECYZJI','Otwarte zadania SEO z terminem ≤7 dni',seoDue.length,seoDue.length?'UWAGA':'OK','Powstają wyłącznie z potwierdzonych problemów audytu.',links.seo),
  metric('RES_OUT_SENT','WYNIKI 30 DNI','Wysłane kontakty medialne',sent30.length,'INFO','Liczone wyłącznie po Gmail_Message_ID i Sent_At.',links.outreach),
  metric('RES_OUT_REPLY','WYNIKI 30 DNI','Odpowiedzi na outreach',replies30.length,replies30.length?'OK':'INFO','Każda odpowiedź pochodzi z istniejącego wątku Gmail.',links.outreach),
  metric('RES_MEDIA','WYNIKI 30 DNI','Potwierdzone publikacje / emisje',media30.length,'INFO','Wynik liczy się dopiero z URL-em i datą publikacji.',links.results),
  metric('RES_PLAYLIST','WYNIKI 30 DNI','Potwierdzone placementy',playlist30.length,'INFO','Liczone wyłącznie z potwierdzonego Placement_URL.',links.results),
  metric('RES_SOCIAL','WYNIKI 30 DNI','Opublikowane materiały social',social30.length,'INFO','Liczone po Published_At i ID publikacji.',links.social),
  metric('RES_OPPS','WYNIKI 30 DNI','Nowe okazje znalezione',opps30.length,'INFO','Kandydaci Opportunity Scout; nie każdy wymaga działania.',links.scout),
  metric('NEXT_FOLLOWUP','NAJBLIŻSZY TERMIN','Najbliższy follow-up',nextFollowup || 'Brak','INFO','Pierwszy przyszły, nieobsłużony Follow_Up_At.',links.outreach),
  metric('NEXT_DEADLINE','NAJBLIŻSZY TERMIN','Najbliższy deadline okazji',nextDeadline || 'Brak potwierdzonego',nextDeadline?'UWAGA':'OK','Brak wpisanej daty nie jest traktowany jako deadline.',links.scout),
  metric('NEXT_SOCIAL','NAJBLIŻSZY TERMIN','Najbliższa zatwierdzona publikacja',nextSocial || 'Brak',nextSocial?'INFO':'OK','Pokazuje tylko APPROVED z realnym plikiem assetu.',links.social),
  metric('SYS_AI','SYSTEM','Gemini AI visibility',aiValue,aiStatus,aiLimited?'Ostatni run dostał 429; paczka pozostaje do ponowienia.':aiError?'Ostatni run zakończył się błędem danych.':'Ostatni zapis AI visibility jest dostępny.',links.seo),
  metric('SYS_FRESH','SYSTEM','Świeżość danych',latestActivity?localStamp(latestActivity):'Brak danych',freshHours<=48?'OK':'UWAGA',freshHours<=48?'Ostatnia aktywność źródeł mieści się w 48 godzinach.':'Brak świeżej aktywności źródeł od ponad 48 godzin.',links.backend),
  metric('SYS_REFRESH','SYSTEM','Ostatnie odświeżenie Cockpitu',refresh,'OK','VIRYA 00 przebudował widok automatycznie.',links.cockpit)
];
return out.map(json => ({json}));

const data=$getWorkflowStaticData('global');
const now=new Date();
const stamp=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Warsaw',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(now);
const day=stamp.slice(0,10);
if(data.lastSnapshotDate===day)return[];
data.lastSnapshotDate=day;
return $input.all().map(i=>{const r=i.json||{};return{json:{Snapshot_Date:day,Metric_ID:r.Metric_ID||'',Area:r.Obszar||'',Metric:r.Wskaźnik||'',Value:r.Wartość??'',Status:r.Status||'',Detail:r['Co to znaczy']||'',Source:'VIRYA 00 — Cockpit Rebuilder',Updated_At:r.Odświeżono||stamp,Link:r.Link||''}}});
